import React, { useState } from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, Image, TextInput } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

type Specialty = {
  id: number;
  name: string;
  icon: keyof typeof Ionicons.glyphMap;
};

export default function ExploreScreen() {
  const [searchQuery, setSearchQuery] = useState('');

  const specialties: Specialty[] = [
    { id: 1, name: 'Cardiology', icon: 'heart' },
    { id: 2, name: 'Dermatology', icon: 'bandage' },
    { id: 3, name: 'Neurology', icon: 'pulse' },
    { id: 4, name: 'Pediatrics', icon: 'people' },
    { id: 5, name: 'Orthopedics', icon: 'fitness' },
    { id: 6, name: 'Ophthalmology', icon: 'eye' },
  ];

  const doctors = [
    {
      id: 1,
      name: 'Dr. Sarah Wilson',
      specialty: 'Cardiologist',
      rating: 4.8,
      reviews: 124,
      image: 'https://randomuser.me/api/portraits/women/32.jpg',
      experience: '15 years',
      location: 'City Hospital'
    },
    {
      id: 2,
      name: 'Dr. James Brown',
      specialty: 'Dermatologist',
      rating: 4.7,
      reviews: 98,
      image: 'https://randomuser.me/api/portraits/men/45.jpg',
      experience: '12 years',
      location: 'Medical Center'
    },
    {
      id: 3,
      name: 'Dr. Emily Davis',
      specialty: 'Pediatrician',
      rating: 4.9,
      reviews: 156,
      image: 'https://randomuser.me/api/portraits/women/68.jpg',
      experience: '10 years',
      location: 'Children\'s Hospital'
    },
  ];

  return (
    <ScrollView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Explore</Text>
      </View>

      {/* Search Bar */}
      <View style={styles.searchContainer}>
        <Ionicons name="search" size={20} color="#666" style={styles.searchIcon} />
        <TextInput
          style={styles.searchInput}
          placeholder="Search doctors, specialties..."
          value={searchQuery}
          onChangeText={setSearchQuery}
          placeholderTextColor="#666"
        />
      </View>

      {/* Specialties */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Specialties</Text>
        <ScrollView horizontal showsHorizontalScrollIndicator={false}>
          {specialties.map((specialty) => (
            <TouchableOpacity key={specialty.id} style={styles.specialtyCard}>
              <View style={styles.specialtyIcon}>
                <Ionicons name={specialty.icon} size={24} color="#007AFF" />
              </View>
              <Text style={styles.specialtyName}>{specialty.name}</Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>

      {/* Top Doctors */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Top Doctors</Text>
        {doctors.map((doctor) => (
          <TouchableOpacity key={doctor.id} style={styles.doctorCard}>
            <Image 
              source={{ uri: doctor.image }}
              style={styles.doctorImage}
            />
            <View style={styles.doctorInfo}>
              <Text style={styles.doctorName}>{doctor.name}</Text>
              <Text style={styles.doctorSpecialty}>{doctor.specialty}</Text>
              <View style={styles.ratingContainer}>
                <Ionicons name="star" size={16} color="#FFD700" />
                <Text style={styles.rating}>{doctor.rating}</Text>
                <Text style={styles.reviews}>({doctor.reviews} reviews)</Text>
              </View>
              <View style={styles.doctorDetails}>
                <View style={styles.detailItem}>
                  <Ionicons name="time" size={16} color="#666" />
                  <Text style={styles.detailText}>{doctor.experience} experience</Text>
                </View>
                <View style={styles.detailItem}>
                  <Ionicons name="location" size={16} color="#666" />
                  <Text style={styles.detailText}>{doctor.location}</Text>
                </View>
              </View>
            </View>
            <TouchableOpacity style={styles.bookButton}>
              <Text style={styles.bookButtonText}>Book</Text>
            </TouchableOpacity>
          </TouchableOpacity>
        ))}
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#F5F5F5',
  },
  header: {
    padding: 20,
    backgroundColor: '#fff',
  },
  headerTitle: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#333',
  },
  searchContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#fff',
    margin: 20,
    padding: 15,
    borderRadius: 10,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  searchIcon: {
    marginRight: 10,
  },
  searchInput: {
    flex: 1,
    fontSize: 16,
    color: '#333',
  },
  section: {
    padding: 20,
  },
  sectionTitle: {
    fontSize: 18,
    fontWeight: 'bold',
    marginBottom: 15,
    color: '#333',
  },
  specialtyCard: {
    backgroundColor: '#fff',
    borderRadius: 15,
    padding: 15,
    marginRight: 15,
    alignItems: 'center',
    width: 100,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  specialtyIcon: {
    width: 50,
    height: 50,
    borderRadius: 25,
    backgroundColor: '#E3F2FD',
    justifyContent: 'center',
    alignItems: 'center',
    marginBottom: 10,
  },
  specialtyName: {
    fontSize: 12,
    color: '#333',
    textAlign: 'center',
  },
  doctorCard: {
    backgroundColor: '#fff',
    borderRadius: 15,
    padding: 15,
    marginBottom: 15,
    flexDirection: 'row',
    alignItems: 'center',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  doctorImage: {
    width: 80,
    height: 80,
    borderRadius: 40,
    marginRight: 15,
  },
  doctorInfo: {
    flex: 1,
  },
  doctorName: {
    fontSize: 16,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 5,
  },
  doctorSpecialty: {
    fontSize: 14,
    color: '#666',
    marginBottom: 5,
  },
  ratingContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 5,
  },
  rating: {
    marginLeft: 5,
    color: '#333',
    fontWeight: '500',
  },
  reviews: {
    marginLeft: 5,
    color: '#666',
    fontSize: 12,
  },
  doctorDetails: {
    flexDirection: 'row',
    flexWrap: 'wrap',
  },
  detailItem: {
    flexDirection: 'row',
    alignItems: 'center',
    marginRight: 15,
    marginTop: 5,
  },
  detailText: {
    marginLeft: 5,
    color: '#666',
    fontSize: 12,
  },
  bookButton: {
    backgroundColor: '#007AFF',
    paddingHorizontal: 20,
    paddingVertical: 10,
    borderRadius: 20,
    marginLeft: 10,
  },
  bookButtonText: {
    color: '#fff',
    fontWeight: '500',
  },
});
